<form class="wp-hcin__book" data-reveal="up" style="--i:4" onsubmit="return false">${(e.search?.fields||[["calendar","Arrival","Fri, 16 Oct"],["calendar","Departure","Mon, 19 Oct"],["users","Guests","2 adults"]]).map(([t,r,s])=>`<label>${x(t)}<span><small>${i(r)}</small><input value="${i(s)}" aria-label="${i(r)}"></span></label>`).join("")}<button class="wp-btn wp-btn--primary wp-btn--lg">${i(e.cta||"Check availability")}</button></form></div></div>`),css:`
